<?php
declare(strict_types=1);
$pageTitle='Action Editor';$topNavSection='configuration';$BODY_CLASS='hub-page';require __DIR__.'/ui_bootstrap.php';$actions=$uiRepository->rows('actions');$policies=$uiRepository->rows('action_policies');$installations=$uiRepository->rows('installations');$profiles=$uiRepository->rows('characters');$embedded=($_GET['embed']??'')==='1';include __DIR__.'/tmpl/head.html';if(!$embedded)include __DIR__.'/tmpl/navbar.php';
$policyFields=static function(array$content,array$actions):void{ ?><div class="almsivi-form-grid"><label><span><input type="checkbox" name="enabled" value="1"<?php echo ($content['enabled']??true)===true?' checked':''; ?>> Enable this policy</span></label><label>Maximum action tier<select name="max_tier"><?php for($tier=0;$tier<=3;$tier++): ?><option value="<?php echo $tier; ?>"<?php echo (int)($content['max_tier']??1)===$tier?' selected':''; ?>>Tier <?php echo $tier; ?></option><?php endfor; ?></select></label><fieldset class="almsivi-group wide"><legend>Allowed OpenMW actions</legend><?php foreach($actions as$action):$name=(string)$action['action_name'];$enabled=isset($content['actions'])?($content['actions'][$name]??false)===true:(bool)$action['enabled']; ?><label><span><input type="checkbox" name="allowed_actions[]" value="<?php echo almsivi_ui_h($name); ?>"<?php echo $enabled?' checked':''; ?>> <?php echo almsivi_ui_h($name); ?> <small>Tier <?php echo almsivi_ui_h($action['tier']); ?> — <?php echo almsivi_ui_h($action['description']); ?></small></span></label><?php endforeach; ?></fieldset></div><?php };
?>
<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>Action Editor</h1><p>Allow only actions advertised by the OpenMW client. Server policy cannot invent Lua commands or bypass negotiated capabilities.</p></div><span class="almsivi-badge"><?php echo count($actions); ?> negotiated actions</span></header><?php if(isset($_GET['status'])): ?><div class="almsivi-status">Action policy saved.</div><?php endif; ?>
<section class="almsivi-card"><h2>Create action policy</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/action-policy-controls-create"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Policy name<input name="name" required maxlength="128"></label><label>NPC profile (optional)<select name="profile_id"><option value="">Installation-wide</option><?php foreach($profiles as$row): ?><option value="<?php echo almsivi_ui_h($row['profile_id']); ?>"><?php echo almsivi_ui_h($row['name']); ?></option><?php endforeach; ?></select></label></div><?php $policyFields([], $actions); ?><div class="almsivi-actions"><button type="submit">Create Policy</button></div></form></section>
<section class="almsivi-grid"><?php foreach($policies as$row):$content=is_array($row['content'])?$row['content']:[]; ?><article class="almsivi-card"><div class="almsivi-card-header"><div><h2><?php echo almsivi_ui_h($row['name']); ?></h2><p class="almsivi-muted"><?php echo almsivi_ui_h($row['profile_name']??'Installation-wide'); ?></p></div><span class="almsivi-badge">Revision <?php echo almsivi_ui_h($row['current_revision']); ?></span></div><details><summary>Edit policy</summary><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/action-policy-controls-revise"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="configuration_id" value="<?php echo almsivi_ui_h($row['configuration_id']); ?>"><?php $policyFields($content,$actions); ?><label>Revision note<input name="change_reason" required value="Management action policy update"></label><div class="almsivi-actions"><button type="submit">Save Revision</button></div></form></details></article><?php endforeach; ?><?php if($policies===[]): ?><article class="almsivi-card almsivi-empty">No custom action policies exist yet.</article><?php endif; ?></section></main><?php include __DIR__.'/tmpl/footer.html'; ?>
